    .bottom-workspace-grid { display: grid; gap: 16px; }
    .editor-terminal-grid { grid-template-columns: minmax(0, 1.15fr) 360px; }
    .bottom-workspace-grid { grid-template-columns: minmax(0, 1fr) 320px; margin-top: 16px; }
    .editor-code {
      min-height: 320px;
      border-radius: 20px;
      background: rgba(5,10,20,0.6);
      border: 1px solid rgba(255,255,255,0.08);
    }
    .terminal-log {
      display: grid;
      gap: 10px;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    }
    .terminal-log div,
    .test-item {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
    }
    .preview-frame {
      min-height: 240px;
      display: grid;
      place-items: center;
      padding: 16px;
    }
    .mini-app {
      width: min(100%, 420px);
      padding: 14px;
      border-radius: 28px;
      display: grid;
      gap: 12px;
    }
    .mini-topbar { height: 34px; border-radius: 16px; background: rgba(255,255,255,0.1); }
    .mini-body { display: grid; grid-template-columns: 92px minmax(0,1fr); gap: 12px; }
    .mini-sidebar,
    .mini-main,
    .mini-message,
    .mini-input {
      border-radius: 18px;
      background: rgba(255,255,255,0.08);
    }
    .mini-sidebar { min-height: 180px; }
    .mini-main { padding: 12px; display: grid; gap: 10px; }
    .mini-message.one { height: 42px; width: 72%; }
    .mini-message.two { height: 84px; }
    .mini-input { height: 46px; margin-top: auto; }
    .workflow-grid { grid-template-columns: minmax(0, 1.2fr) 360px; }
    .canvas-surface {
      position: relative;
      min-height: 520px;
      border-radius: 24px;
      background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
      border: 1px solid rgba(255,255,255,0.08);
      overflow: hidden;
    }
    .workflow-lines {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
    }
    .workflow-lines path {
      fill: none;
      stroke: rgba(126,182,255,0.7);
      stroke-width: 1.4;
      stroke-linecap: round;
      stroke-dasharray: 1.4 2.8;
    }
    .workflow-node {
      position: absolute;
      width: 150px;
      padding: 14px;
      border-radius: 22px;
      background: linear-gradient(180deg, rgba(255,255,255,0.16), rgba(255,255,255,0.06));
      border: 1px solid rgba(255,255,255,0.16);
      box-shadow: inset 0 1px 0 rgba(255,255,255,0.24), 0 20px 50px rgba(0,0,0,0.22);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
    }
    .toolbar {
      margin-top: 14px;
      padding: 10px;
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 8px;
    }
    .voice-meter {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      align-items: end;
      gap: 8px;
      min-height: 84px;
    }
    .voice-meter span {
      border-radius: 999px;
      background: linear-gradient(180deg, rgba(133,188,255,0.9), rgba(82,131,255,0.32));
      animation: meter 1.2s ease-in-out infinite;
    }
    .voice-meter span:nth-child(1) { height: 26px; animation-delay: 0s; }
    .voice-meter span:nth-child(2) { height: 48px; animation-delay: 0.1s; }
    .voice-meter span:nth-child(3) { height: 72px; animation-delay: 0.2s; }
    .voice-meter span:nth-child(4) { height: 58px; animation-delay: 0.3s; }
    .voice-meter span:nth-child(5) { height: 74px; animation-delay: 0.4s; }
    .voice-meter span:nth-child(6) { height: 44px; animation-delay: 0.5s; }
    .voice-meter span:nth-child(7) { height: 28px; animation-delay: 0.6s; }
    @keyframes meter {
      0%,100% { transform: scaleY(0.85); opacity: 0.7; }
      50% { transform: scaleY(1.05); opacity: 1; }
    }
    .select-box { display: grid; gap: 6px; padding-top: 10px; padding-bottom: 10px; }
    .select-box label { font-size: 0.8rem; color: var(--text-soft); }
    .audio-player { display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: 12px; align-items: center; padding: 12px; }
    .audio-track {
      height: 10px;
      border-radius: 999px;
      background: rgba(255,255,255,0.08);
      overflow: hidden;
    }
    .audio-track span {
      display: block;
      width: 46%;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, rgba(155,210,255,0.9), rgba(55,118,255,0.8));
    }
    .utilities-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); align-content: start; }
    .accordion { display: grid; gap: 10px; }
    .accordion-item { justify-content: space-between; border-radius: 18px; background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.06); }
    .accordion-content { line-height: 1.65; }
    table { width: 100%; border-collapse: collapse; font-size: 0.92rem; }
    th, td { padding: 12px 14px; text-align: left; }
    thead th { color: var(--text-soft); font-weight: 600; border-bottom: 1px solid rgba(255,255,255,0.08); }
    tbody tr + tr td { border-top: 1px solid rgba(255,255,255,0.06); }
    .control-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .toggle,
    .checkbox {
      display: grid;
      grid-template-columns: auto auto 1fr;
      align-items: center;
      gap: 12px;
      padding: 12px 14px;
    }
    .toggle input,
    .checkbox input { position: absolute; opacity: 0; pointer-events: none; }
    .toggle span {
      width: 44px;
      height: 26px;
      border-radius: 999px;
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.1);
      position: relative;
    }
    .toggle span::after {
      content: "";
      position: absolute;
      width: 18px;
      height: 18px;
      border-radius: 999px;
      top: 3px;
      left: 4px;
      background: linear-gradient(180deg, rgba(255,255,255,0.95), rgba(255,255,255,0.55));
      transition: transform 180ms ease;
    }
    .toggle input:checked + span::after { transform: translateX(17px); }
    .checkbox span {
      width: 20px;
      height: 20px;
      border-radius: 6px;
      background: rgba(255,255,255,0.08);
      border: 1px solid rgba(255,255,255,0.1);
      position: relative;
    }
    .checkbox input:checked + span::after {
      content: "";
      position: absolute;
      inset: 4px;
      border-radius: 3px;
      background: linear-gradient(180deg, rgba(129,189,255,0.94), rgba(55,120,255,0.82));
    }
    .backdrop-overlay {
      position: fixed;
      inset: 0;
      background: rgba(2,8,18,0.45);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      opacity: 0;
      pointer-events: none;
      transition: opacity 200ms ease;
    }
    .backdrop-overlay.open { opacity: 1; pointer-events: auto; }
    .drawer {
      position: fixed;
      right: 18px;
      bottom: 18px;
      width: min(420px, calc(100vw - 36px));
      padding: 16px;
      border-radius: 30px;
      transform: translateY(calc(100% + 24px));
      transition: transform 220ms ease;
      z-index: 20;
    }
    .drawer.open { transform: translateY(0); }
    .drawer-handle {
      width: 54px;
      height: 6px;
      border-radius: 999px;
      background: rgba(255,255,255,0.22);
      margin: 0 auto 12px;
    }
    .drawer-content { display: grid; gap: 12px; margin-top: 12px; }
    .drawer-card { padding: 14px; }
    .toast-stack {
      position: fixed;
      top: 24px;
      right: 24px;
      display: grid;
      gap: 12px;
      z-index: 30;
    }
    .toast {
      min-width: 300px;
      padding: 14px 16px;
      display: grid;
      gap: 6px;
      animation: toastIn 220ms ease;
    }
    @keyframes toastIn {
      from { opacity: 0; transform: translateY(-8px) scale(0.98); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }
    .mobile-only { display: none; }
    ::-webkit-scrollbar { width: 10px; height: 10px; }
    ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.12); border-radius: 999px; }
    ::-webkit-scrollbar-track { background: transparent; }
    @media (max-width: 1280px) {
      .conversation-layout,
      .workflow-grid,
      .editor-terminal-grid,
      .bottom-workspace-grid,
      .utilities-grid { grid-template-columns: 1fr; }
      .suggestions-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (max-width: 980px) {
      body { overflow: auto; }
      .app-shell { grid-template-columns: 1fr; min-height: auto; }
      .sidebar {
        position: fixed;
        inset: 18px auto 18px 18px;
        width: min(320px, calc(100vw - 36px));
        z-index: 25;
        transform: translateX(calc(-100% - 24px));
        transition: transform 220ms ease;
      }
      .sidebar.open { transform: translateX(0); }
      .content-area { min-width: 0; }
      .mobile-only { display: grid; }
      .topbar,
      .panel-header,
      .topbar-actions,
      .composer-top,
      .composer-bottom { flex-wrap: wrap; }
      .composer-top { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .workspace-grid { grid-template-columns: 1fr; }
      .main-panel { position: relative; min-height: auto; }
      .main-grid { display: grid; }
    }
    @media (max-width: 720px) {
      .app-shell { padding: 12px; gap: 12px; }
      .topbar,
      .chat-column,
      .utility-card,
      .workspace-sidebar,
      .editor-panel,
      .terminal-panel,
      .preview-panel,
      .results-panel,
      .canvas-panel { padding: 14px; }
      .sidebar { inset: 12px auto 12px 12px; min-height: calc(100vh - 24px); }
      .suggestions-row,
      .attachment-gallery,
      .control-grid,
      .toolbar,
      .feedback-bar { grid-template-columns: 1fr; }
      .composer-top { grid-template-columns: 1fr; }
      .attachment-strip { grid-template-columns: 1fr; }
    }
  </style>
</head>
