  <script>
    const navItems = document.querySelectorAll('.nav-item');
    const panels = document.querySelectorAll('.main-panel');
    const themeToggle = document.getElementById('themeToggle');
    const root = document.documentElement;
    const sidebar = document.getElementById('sidebar');
    const sidebarOpen = document.getElementById('sidebarOpen');
    const sidebarClose = document.getElementById('sidebarClose');
    const backdrop = document.getElementById('backdrop');
    const drawer = document.getElementById('drawer');
    const openDrawer = document.getElementById('openDrawer');
    const closeDrawer = document.getElementById('closeDrawer');
    const showToast = document.getElementById('showToast');
    const toastStack = document.getElementById('toastStack');
    const feedbackSegments = document.querySelectorAll('.feedback-segment');
    const accordionItems = document.querySelectorAll('.accordion-item');
    const promptComposer = document.getElementById('promptComposer');

    function setPanel(panelName) {
      navItems.forEach(item => item.classList.toggle('active', item.dataset.panel === panelName));
      panels.forEach(panel => panel.classList.toggle('active', panel.id === `panel-${panelName}`));
    }

    navItems.forEach(item => {
      item.addEventListener('click', () => setPanel(item.dataset.panel));
    });

    function updateThemeIcon() {
      const isDark = root.getAttribute('data-theme') === 'dark';
      themeToggle.innerHTML = isDark
        ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3a9 9 0 1 0 9 9c0-.35-.02-.69-.06-1.02A7 7 0 0 1 12 3Z"></path></svg>'
        : '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="5"></circle><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"></path></svg>';
    }

    updateThemeIcon();

    themeToggle.addEventListener('click', () => {
      root.setAttribute('data-theme', root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark');
      updateThemeIcon();
    });

    function openSidebar() {
      sidebar.classList.add('open');
      backdrop.classList.add('open');
    }

    function closeSidebarPanel() {
      sidebar.classList.remove('open');
      if (!drawer.classList.contains('open')) {
        backdrop.classList.remove('open');
      }
    }

    function openDrawerPanel() {
      drawer.classList.add('open');
      backdrop.classList.add('open');
    }

    function closeDrawerPanel() {
      drawer.classList.remove('open');
      if (!sidebar.classList.contains('open')) {
        backdrop.classList.remove('open');
      }
    }

    sidebarOpen.addEventListener('click', openSidebar);
    if (sidebarClose) {
      sidebarClose.addEventListener('click', closeSidebarPanel);
    }
    openDrawer.addEventListener('click', openDrawerPanel);
    closeDrawer.addEventListener('click', closeDrawerPanel);
    backdrop.addEventListener('click', () => {
      closeSidebarPanel();
      closeDrawerPanel();
    });

    feedbackSegments.forEach(segment => {
      segment.addEventListener('click', () => {
        feedbackSegments.forEach(node => node.classList.remove('active'));
        segment.classList.add('active');
        createToast('Feedback saved', `${segment.textContent} rating has been recorded.`);
      });
    });

    accordionItems.forEach(item => {
      item.addEventListener('click', () => {
        accordionItems.forEach(node => {
          node.classList.remove('active');
          node.setAttribute('aria-expanded', 'false');
        });
        item.classList.add('active');
        item.setAttribute('aria-expanded', 'true');
      });
    });

    function createToast(title, description) {
      const toast = document.createElement('div');
      toast.className = 'toast glass glass-elevated';
      const strong = document.createElement('strong');
      strong.textContent = title;
      const span = document.createElement('span');
      span.textContent = description;
      toast.appendChild(strong);
      toast.appendChild(span);
      toastStack.appendChild(toast);
      window.setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(-8px)';
        toast.style.transition = 'opacity 180ms ease, transform 180ms ease';
        window.setTimeout(() => {
          if (toast.parentNode) {
            toast.parentNode.removeChild(toast);
          }
        }, 180);
      }, 3200);
    }

    showToast.addEventListener('click', () => {
      createToast('Component library ready', 'Liquid glass UI elements are synchronized and available.');
    });

    promptComposer.addEventListener('submit', event => {
      event.preventDefault();
      createToast('Prompt queued', 'Your message has been captured by the composer.');
    });

    window.addEventListener('resize', () => {
      if (window.innerWidth > 980) {
        sidebar.classList.remove('open');
        if (!drawer.classList.contains('open')) {
          backdrop.classList.remove('open');
        }
      }
    });
  </script>
</body>
</html>
